declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_admin();require_once __DIR__.'/../includes/gemini_transport.php';$db=db();
function aq_python():string{if(PHP_OS_FAMILY!=='Windows')return 'python3';$base=(string)getenv('LOCALAPPDATA');$m=$base!==''?glob($base.'/Programs/Python/Python*/python.exe'):[];if($m){sort($m,SORT_NATURAL);return (string)end($m);}return 'python';}
function aq_pdf(string $path):string{$pipes=[];$p=proc_open([aq_python(),__DIR__.'/../scripts/extract_curriculum_pdf.py',$path,'auto'],[['pipe','r'],['pipe','w'],['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);if(!is_resource($p))throw new RuntimeException('PDF reader could not start.');fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0)throw new RuntimeException('PDF reading failed: '.$err);return trim((string)(json_decode((string)$out,true,512,JSON_THROW_ON_ERROR)['text']??''));}
function aq_upload(string $name,bool $required=true):?array{if(!isset($_FILES[$name])||$_FILES[$name]['error']===UPLOAD_ERR_NO_FILE){if($required)throw new RuntimeException('Select the question PDF.');return null;}$f=$_FILES[$name];if($f['error']!==UPLOAD_ERR_OK||$f['size']>30*1024*1024||file_get_contents($f['tmp_name'],false,null,0,5)!=='%PDF-')throw new RuntimeException('Use a valid PDF no larger than 30 MB.');return $f;}
function aq_ai(string $prompt):array{if(GEMINI_API_KEY==='')throw new RuntimeException('GEMINI_API_KEY is required.');$string=['type'=>'STRING'];$schema=['type'=>'ARRAY','items'=>['type'=>'OBJECT','properties'=>['number'=>$string,'question'=>$string,'option_a'=>$string,'option_b'=>$string,'option_c'=>$string,'option_d'=>$string,'correct_option'=>['type'=>'STRING','enum'=>['a','b','c','d']],'explanation'=>$string],'required'=>['question','option_a','option_b','option_c','option_d','correct_option']]];$parts=[['text'=>mb_substr($prompt,0,95000).' Read the attached PDF pages visually when embedded text is missing.']];$total=0;foreach(['question_pdf','answer_pdf'] as $name){$path=(string)($_FILES[$name]['tmp_name']??'');if($path===''||!is_file($path))continue;$size=(int)filesize($path);$total+=$size;if($size<=12*1024*1024&&$total<=18*1024*1024)$parts[]=['inlineData'=>['mimeType'=>'application/pdf','data'=>base64_encode((string)file_get_contents($path))]];}$payload=json_encode(['contents'=>[['parts'=>$parts]],'generationConfig'=>['responseMimeType'=>'application/json','responseSchema'=>$schema,'temperature'=>0,'maxOutputTokens'=>32768]],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$r=gemini_http_json(GEMINI_API_BASE.rawurlencode(GEMINI_MODEL).':generateContent?key='.rawurlencode(GEMINI_API_KEY),['Content-Type: application/json'],$payload);if($r['status']!==200)throw new RuntimeException('AI document reading failed. '.$r['error']);try{$body=json_decode($r['body'],true,512,JSON_THROW_ON_ERROR);}catch(JsonException $e){throw new RuntimeException('The AI service returned an unreadable response. Please try again.');}$candidate=$body['candidates'][0]??[];$text='';foreach($candidate['content']['parts']??[] as $part)$text.=(string)($part['text']??'');$text=trim($text);$text=preg_replace('/^```(?:json)?\s*|\s*```$/i','',$text)??$text;$first=strpos($text,'[');$last=strrpos($text,']');if($first!==false&&$last!==false&&$last>=$first)$text=substr($text,$first,$last-$first+1);try{$items=json_decode($text,true,512,JSON_THROW_ON_ERROR);}catch(JsonException $e){$reason=(string)($candidate['finishReason']??'');if($reason==='MAX_TOKENS')throw new RuntimeException('The PDF contains too many questions for one import. Split it into smaller PDFs and import each part.');throw new RuntimeException('The AI could not structure the questions. Please retry the import.');}if(!is_array($items))throw new RuntimeException('No quiz questions were returned.');return $items;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=(string)($_POST['action']??'');$db->begin_transaction();if($action==='import_quiz'){$lessonId=filter_input(INPUT_POST,'lesson_id',FILTER_VALIDATE_INT);$medium=(string)($_POST['medium']??'');$activityType=(string)($_POST['activity_type']??'lesson_quiz');if(!in_array($activityType,['lesson_quiz','challenge','missing','matching'],true))throw new RuntimeException('Choose a valid question location.');$lesson=$lessonId?query_one('SELECT * FROM lessons WHERE id=? AND medium=? AND status="active"','is',[$lessonId,$medium]):null;if(!$lesson)throw new RuntimeException('Choose a valid grade, medium, subject and lesson.');$questionFile=aq_upload('question_pdf');$answerFile=aq_upload('answer_pdf',false);$questionText=aq_pdf($questionFile['tmp_name']);$answerText=$answerFile?aq_pdf($answerFile['tmp_name']):'';$prompt='Extract every multiple-choice question exactly as written. Do not paraphrase, summarize, invent, or omit questions. Return JSON only as an array with: number, question, option_a, option_b, option_c, option_d, correct_option (a/b/c/d), explanation. Use the answer sheet when supplied. If the question PDF itself contains answers, use them. QUESTION PDF: '.$questionText.' ANSWER SHEET: '.$answerText;$items=aq_ai($prompt);if(!$items)throw new RuntimeException('No multiple-choice questions were found.');$quiz=query_one('SELECT id FROM quizzes WHERE lesson_id=? ORDER BY id LIMIT 1','i',[$lessonId]);if($quiz)$quizId=(int)$quiz['id'];else{$s=$db->prepare('INSERT INTO quizzes(grade_id,subject_id,unit_id,lesson_id,timer_minutes,pass_mark,status) VALUES(?,?,?,?,15,50,"active")');$s->bind_param('iiii',$lesson['grade_id'],$lesson['subject_id'],$lesson['unit_id'],$lessonId);$s->execute();$quizId=(int)$db->insert_id;}$replace=!empty($_POST['replace_existing']);if($replace){$db->query("DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=$quizId AND qq.activity_type='$activityType'");$db->query("DELETE FROM quiz_questions WHERE quiz_id=$quizId AND activity_type='$activityType'");}$field=['Sinhala'=>'si','Tamil'=>'ta','English'=>'en'][$medium];$start=(int)(query_one('SELECT COALESCE(MAX(display_order),0) n FROM quiz_questions WHERE quiz_id=? AND activity_type=?','is',[$quizId,$activityType])['n']??0);$added=0;foreach($items as $i=>$x){$q=trim((string)($x['question']??''));$correct=strtolower((string)($x['correct_option']??''));if($q===''||!in_array($correct,['a','b','c','d'],true))continue;$options=[];foreach(['a','b','c','d'] as $o)$options[$o]=trim((string)($x['option_'.$o]??''));if(in_array('',array_values($options),true))continue;$explanation=trim((string)($x['explanation']??''));$order=$start+$i+1;$sql="INSERT INTO quiz_questions(quiz_id,activity_type,question_$field,option_a_$field,option_b_$field,option_c_$field,option_d_$field,correct_option,explanation_$field,display_order,status) VALUES(?,?,?,?,?,?,?,?,?,?,\"active\")";$s=$db->prepare($sql);$s->bind_param('issssssssi',$quizId,$activityType,$q,$options['a'],$options['b'],$options['c'],$options['d'],$correct,$explanation,$order);$s->execute();$added++;}if(!$added)throw new RuntimeException('Questions were read, but usable answers/options were not found. Add an answer sheet.');$message="$added questions imported into the selected lesson.";}elseif($action==='delete_quiz'){$id=filter_input(INPUT_POST,'quiz_id',FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Invalid quiz.');$s=$db->prepare('DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=?');$s->bind_param('i',$id);$s->execute();$s=$db->prepare('DELETE FROM quiz_attempts WHERE quiz_id=?');$s->bind_param('i',$id);$s->execute();$s=$db->prepare('DELETE FROM quizzes WHERE id=?');$s->bind_param('i',$id);$s->execute();$message='Quiz and its Practice Lab questions removed.';}elseif($action==='delete_question'){$id=filter_input(INPUT_POST,'question_id',FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Invalid question.');$s=$db->prepare('DELETE FROM quiz_answers WHERE question_id=?');$s->bind_param('i',$id);$s->execute();$s=$db->prepare('DELETE FROM quiz_questions WHERE id=?');$s->bind_param('i',$id);$s->execute();$message='Question removed.';}elseif($action==='delete_paper'){$id=filter_input(INPUT_POST,'paper_id',FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Invalid paper.');$s=$db->prepare('DELETE FROM practice_papers WHERE id=?');$s->bind_param('i',$id);$s->execute();$message='Imported paper and all its questions removed.';}else throw new RuntimeException('Unknown action.');$db->commit();flash('success',$message);}catch(Throwable $e){@$db->rollback();flash('error',$e->getMessage());}redirect('admin/assessment_manager.php');}
$grades=$db->query("SELECT id,grade_number FROM grades WHERE status='active' ORDER BY grade_number")->fetch_all(MYSQLI_ASSOC);$subjects=$db->query("SELECT id,grade_id,name_en,name_si,name_ta FROM subjects WHERE status='active' ORDER BY grade_id,name_en")->fetch_all(MYSQLI_ASSOC);$lessons=$db->query("SELECT id,grade_id,subject_id,medium,display_order,title_en,title_si,title_ta FROM lessons WHERE status='active' AND content_source='textbook' ORDER BY grade_id,medium,subject_id,display_order")->fetch_all(MYSQLI_ASSOC);$quizzes=$db->query("SELECT q.id,q.lesson_id,q.grade_id,q.subject_id,COALESCE(q.title_en,q.title_si,q.title_ta,'Lesson quiz') title,g.grade_number,l.medium,s.name_en subject,COALESCE(l.title_en,l.title_si,l.title_ta) lesson,(SELECT COUNT(*) FROM quiz_questions x WHERE x.quiz_id=q.id) questions FROM quizzes q JOIN lessons l ON l.id=q.lesson_id JOIN grades g ON g.id=q.grade_id JOIN subjects s ON s.id=q.subject_id ORDER BY q.id DESC")->fetch_all(MYSQLI_ASSOC);$questions=$db->query("SELECT x.id,x.quiz_id,x.activity_type,q.grade_id,q.subject_id,l.medium,COALESCE(x.question_en,x.question_si,x.question_ta) question FROM quiz_questions x JOIN quizzes q ON q.id=x.quiz_id JOIN lessons l ON l.id=q.lesson_id ORDER BY x.quiz_id DESC,x.display_order,x.id")->fetch_all(MYSQLI_ASSOC);$papers=$db->query("SELECT p.id,p.title,p.medium,p.grade_id,p.subject_id,g.grade_number,s.name_en subject,(SELECT COUNT(*) FROM paper_questions x WHERE x.paper_id=p.id) questions FROM practice_papers p JOIN grades g ON g.id=p.grade_id JOIN subjects s ON s.id=p.subject_id ORDER BY p.id DESC")->fetch_all(MYSQLI_ASSOC);$activityLabels=['lesson_quiz'=>'Lesson Quiz','challenge'=>'Quick Challenge','missing'=>'Missing Answer','matching'=>'Matching Mission'];$pageTitle='Assessment Manager';include __DIR__.'/_top.php';
?>
<style>.am-hero{background:linear-gradient(135deg,#071a35,#075da4 58%,#00a1a7);color:#fff}.am-hero p{color:#d9efff}.am-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.wide{grid-column:1/-1}.manage-filter{display:grid;grid-template-columns:repeat(3,minmax(0,240px)) auto;gap:12px;align-items:end}.manage-filter button{min-height:46px}.manage-row{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid var(--line)}.manage-row[hidden]{display:none}.manage-row:last-child{border:0}.content-location{display:block;margin-top:5px;color:var(--muted);font-size:.74rem;font-weight:750}.filter-empty{display:none;padding:18px 0;color:var(--muted)}.danger{background:#fff0f2!important;color:#b4233d!important;box-shadow:none!important}.tiny{padding:7px 10px;min-height:36px}@media(max-width:700px){.am-grid,.manage-filter{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
<section class="card am-hero"><span class="badge">Assessment workspace</span><h1>Questions, Quizzes & Practice Labs</h1><p>Select the exact curriculum location, import questions from PDF, and manage old content from one screen.</p></section>
<section class="card"><h2>Import question PDF</h2><form method="post" enctype="multipart/form-data" class="am-grid"><?=csrf_field()?><input type="hidden" name="action" value="import_quiz"><label>Question location<select name="activity_type" required><option value="lesson_quiz">Lesson Quiz</option><option value="challenge">Quick Challenge</option><option value="missing">Missing Answer</option><option value="matching">Matching Mission</option></select></label><label>Grade<select id="amGrade" required><option value="">Choose grade</option><?php foreach($grades as $g):?><option value="<?=$g['id']?>">Grade <?=$g['grade_number']?></option><?php endforeach;?></select></label><label>Medium<select id="amMedium" name="medium" required><option value="">Choose medium</option><option>Sinhala</option><option>Tamil</option><option>English</option></select></label><label>Subject<select id="amSubject" required><option value="">Choose subject</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" data-grade="<?=$s['grade_id']?>"><?=e($s['name_en'])?></option><?php endforeach;?></select></label><label>Lesson<select id="amLesson" name="lesson_id" required><option value="">Choose lesson</option><?php foreach($lessons as $l):?><option value="<?=$l['id']?>" data-grade="<?=$l['grade_id']?>" data-medium="<?=e($l['medium'])?>" data-subject="<?=$l['subject_id']?>">Lesson <?=$l['display_order']?> · <?=e($l['title_en']?:$l['title_si']?:$l['title_ta'])?></option><?php endforeach;?></select></label><label>Question PDF<input type="file" name="question_pdf" accept=".pdf,application/pdf" required></label><label>Answer sheet PDF <small class="muted">recommended</small><input type="file" name="answer_pdf" accept=".pdf,application/pdf"></label><label class="wide"><input type="checkbox" name="replace_existing" value="1" style="width:auto;min-height:auto"> Remove old questions from the selected location before importing</label><button class="wide">Read PDF and import exact questions</button></form></section>
<section class="card"><h2>Filter assessment content</h2><div class="manage-filter"><label>Grade<select id="manageGrade"><option value="">All grades</option><?php foreach($grades as $g):?><option value="<?=$g['id']?>">Grade <?=$g['grade_number']?></option><?php endforeach;?></select></label><label>Medium<select id="manageMedium"><option value="">All mediums</option><option>Sinhala</option><option>Tamil</option><option>English</option></select></label><label>Subject<select id="manageSubject"><option value="">All subjects</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" data-grade="<?=$s['grade_id']?>"><?=e($s['name_en'])?></option><?php endforeach;?></select></label><button type="button" id="clearManageFilter" class="secondary">Clear filters</button></div></section>
<section class="card assessment-list"><h2>Existing quizzes and Practice Labs</h2><?php foreach($quizzes as $q):?><div class="manage-row" data-grade="<?=$q['grade_id']?>" data-subject="<?=$q['subject_id']?>"><div><strong>Grade <?=$q['grade_number']?> · <?=e($q['medium'])?> · <?=e($q['subject'])?></strong><div><?=e($q['lesson'])?> · <?=$q['questions']?> questions</div><small class="content-location">Used in: Lesson Quiz · Quick Challenge · Missing Answer · Matching Mission</small></div><form method="post" onsubmit="return confirm('Remove this quiz and all Practice Lab questions?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_quiz"><input type="hidden" name="quiz_id" value="<?=$q['id']?>"><button class="danger tiny">Remove quiz</button></form></div><?php endforeach;?><div class="filter-empty">No quizzes match the selected filters.</div></section>
<section class="card assessment-list"><h2>Individual questions</h2><div class="scroll" style="max-height:520px"><?php foreach($questions as $q):?><div class="manage-row" data-grade="<?=$q['grade_id']?>" data-subject="<?=$q['subject_id']?>"><span><?=e(mb_strimwidth($q['question'],0,170,'…'))?><small class="content-location"><?=e($activityLabels[$q['activity_type']]??'Unknown location')?></small></span><form method="post" onsubmit="return confirm('Remove this question?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><button class="danger tiny">Remove</button></form></div><?php endforeach;?><div class="filter-empty">No questions match the selected filters.</div></div></section>
<section class="card assessment-list"><h2>Imported papers</h2><?php foreach($papers as $p):?><div class="manage-row" data-grade="<?=$p['grade_id']?>" data-subject="<?=$p['subject_id']?>"><div><strong><?=e($p['title'])?></strong><div class="muted">Grade <?=$p['grade_number']?> · <?=e($p['medium'])?> · <?=e($p['subject'])?> · <?=$p['questions']?> questions</div><small class="content-location">Used in: Paper Practice</small></div><form method="post" onsubmit="return confirm('Remove this paper and every structured question?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_paper"><input type="hidden" name="paper_id" value="<?=$p['id']?>"><button class="danger tiny">Remove paper</button></form></div><?php endforeach;?><div class="filter-empty">No papers match the selected filters.</div></section>
<script>const grade=document.querySelector('#amGrade'),medium=document.querySelector('#amMedium'),subject=document.querySelector('#amSubject'),lesson=document.querySelector('#amLesson');function filter(){[...subject.options].forEach(o=>o.hidden=o.value&&o.dataset.grade!==grade.value);if(subject.selectedOptions[0]?.hidden)subject.value='';[...lesson.options].forEach(o=>o.hidden=o.value&&(o.dataset.grade!==grade.value||o.dataset.medium!==medium.value||o.dataset.subject!==subject.value));if(lesson.selectedOptions[0]?.hidden)lesson.value=''}grade.onchange=medium.onchange=subject.onchange=filter;filter();const listMediums=<?=json_encode([array_column($quizzes,'medium'),array_column($questions,'medium'),array_column($papers,'medium')],JSON_UNESCAPED_UNICODE)?>;document.querySelectorAll('.assessment-list').forEach((list,i)=>list.querySelectorAll('.manage-row').forEach((row,j)=>row.dataset.medium=listMediums[i][j]||''));const manageGrade=document.querySelector('#manageGrade'),manageMedium=document.querySelector('#manageMedium'),manageSubject=document.querySelector('#manageSubject');function filterAssessments(){[...manageSubject.options].forEach(o=>o.hidden=o.value&&manageGrade.value&&o.dataset.grade!==manageGrade.value);if(manageSubject.selectedOptions[0]?.hidden)manageSubject.value='';document.querySelectorAll('.assessment-list').forEach(list=>{let visible=0;list.querySelectorAll('.manage-row').forEach(row=>{const show=(!manageGrade.value||row.dataset.grade===manageGrade.value)&&(!manageMedium.value||row.dataset.medium===manageMedium.value)&&(!manageSubject.value||row.dataset.subject===manageSubject.value);row.hidden=!show;if(show)visible++});list.querySelector('.filter-empty').style.display=visible?'none':'block'})}manageGrade.onchange=manageMedium.onchange=manageSubject.onchange=filterAssessments;document.querySelector('#clearManageFilter').onclick=()=>{manageGrade.value='';manageMedium.value='';manageSubject.value='';filterAssessments()};filterAssessments()</script>
<?php include __DIR__.'/../includes/footer.php';
